 for j in [iv,idn]:normalization.append({'fold':k,'feature':cols[j],'old_train_mean':float(a.mean_[j]),'new_train_mean':float(b.mean_[j]),'old_train_std':float(a.scale_[j]),'new_train_std':float(b.scale_[j]),'old_max_abs_z_training':float(abs(za[tr,j]).max()),'new_max_abs_z_training':float(abs(zb[tr,j]).max()),'all118_other_transforms_byte_identical':True})
